"""
Pytest test suite for the API endpoint /store/order/{orderId}.
This suite tests various scenarios including successful deletion, invalid ID, and order not found.
"""

import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Constants
API_SPEC_PATH = 'api.json'
ENDPOINT = '/store/order/{orderId}'
METHOD = 'DELETE'
TEST_DATA_FILENAME = 'store_order_orderId.json'

# Load test data
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / TEST_DATA_FILENAME

def _load_json_file(file_path):
    with open(file_path, 'r') as file:
        return json.load(file)

_ENDPOINT_DATA = _load_json_file(_endpoint_data_path)

# Reusable parametrize args
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = [f"scenario_{i}" for i, _ in enumerate(_ENDPOINT_DATA)]

@pytest.fixture(scope='session')
def swagger_validator():
    return SwaggerSchemaValidator(API_SPEC_PATH)

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_delete_order(api_client, swagger_validator, scenario_case, config_test_data):
    """
    Test the DELETE /store/order/{orderId} endpoint with various scenarios.
    """
    order_id = scenario_case.get('orderId', config_test_data['orderId'])
    expected_status_code = scenario_case['statusCode']
    endpoint = ENDPOINT.format(orderId=order_id)

    # Validate request before sending
    swagger_validator.validate_json({'orderId': order_id}, 'OrderIdSchema')

    # Perform the API request
    response = api_client.delete(endpoint)

    # Validate response status code
    assert response.status_code == expected_status_code, f"Expected {expected_status_code}, got {response.status_code}"

    # Validate response schema
    validation_result = swagger_validator.validate_schema_by_response(endpoint, METHOD, str(response.status_code), response)
    assert validation_result['valid'], f"Schema validation failed: {validation_result.get('message')}"

    # Additional assertions based on scenario
    if expected_status_code == 200:
        assert response.json().get('message') == 'order deleted', "Order deletion message mismatch"
    elif expected_status_code == 400:
        assert 'Invalid ID supplied' in response.text, "Expected 'Invalid ID supplied' error message"
    elif expected_status_code == 404:
        assert 'Order not found' in response.text, "Expected 'Order not found' error message"
    elif expected_status_code == 'default':
        assert not (200 <= response.status_code < 300), "Unexpected success status code for default case"
